"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[9517],{6501(e,a,t){t.r(a),t.d(a,{assets:()=>d,contentTitle:()=>p,default:()=>h,frontMatter:()=>s,metadata:()=>r,toc:()=>c});const r=JSON.parse('{"id":"home","title":"Enterprise AI, Agents & Applied ML","description":"A practical book for moving from enterprise AI delivery and backend platform foundations into agent protocols, applied machine learning, deep learning, LLM fine\u2011tuning, and alignment. It is organized as a sequence of...","source":"@site/docs/home.mdx","sourceDirName":".","slug":"/","permalink":"/tutorials/","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"frontMatter":{"title":"Enterprise AI, Agents & Applied ML","slug":"/","description":"A practical book for moving from enterprise AI delivery and backend platform foundations into agent protocols, applied machine learning, deep learning, LLM fine\u2011tuning, and alignment. It is organized as a sequence of...","sidebar_label":"Book home","pagination_label":"Book home","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","next":{"title":"Reading guide and concept map","permalink":"/tutorials/content-map"}}');var n=t(4848),i=t(8453),l=t(8172);const o=JSON.parse('{"sourcePath":"index.html","route":"/","kind":"home","partId":"book","partLabel":"Enterprise AI, Agents & Applied ML","accent":"blue","heading":"Enterprise AI, Agents & Applied ML","title":"Enterprise AI, Agents & Applied ML","description":"A practical book for moving from enterprise AI delivery and backend platform foundations into agent protocols, applied machine learning, deep learning, LLM fine\u2011tuning, and alignment. It is organized as a sequence of...","readingMinutes":4,"bodyClass":"","normalizeMath":false,"toc":[{"id":"how-to-read-this-book","label":"How to read this book"}],"html":"<section class=\\"tr-hero\\">\\n  <h1>Enterprise AI, Agents &amp; Applied ML</h1>\\n  <p>A practical book for moving from enterprise AI delivery and backend\\n     platform foundations into agent protocols, applied machine learning,\\n     deep learning, LLM fine\u2011tuning, and alignment. It is organized as a\\n     sequence of small-to-large examples: first the mental model, then the\\n     implementation pattern, then the production tradeoffs.</p>\\n  <div class=\\"tr-hero-meta\\">6 parts \xb7 54 chapters + companion labs \xb7 delivery, platform, agents, ML, deep learning, and reference material</div>\\n</section>\\n\\n<div class=\\"tr-paths\\">\\n  <a class=\\"tr-chip\\" href=\\"/tutorials/content-map\\">Reading guide and concept map</a>\\n  <a class=\\"tr-chip\\" href=\\"/tutorials/part1-enterprise-ai-delivery/overview\\">Delivery / Lead path</a>\\n  <a class=\\"tr-chip\\" href=\\"/tutorials/part2-backend-platform-security/overview\\">Backend &amp; platform path</a>\\n  <a class=\\"tr-chip\\" href=\\"/tutorials/part3-agent-protocols/overview\\">Agent systems path</a>\\n  <a class=\\"tr-chip\\" href=\\"/tutorials/part4-ml-foundations/overview\\">ML foundations path</a>\\n  <a class=\\"tr-chip\\" href=\\"/tutorials/part5-deep-learning-and-llms/overview\\">Deep learning &amp; LLM path</a>\\n  <a class=\\"tr-chip\\" href=\\"/tutorials/part6-appendices/overview\\">Appendices</a>\\n</div>\\n\\n<div class=\\"tr-note\\" style=\\"margin: 18px 0 6px;\\">\\n  <strong>Book-wide concept map</strong>\\n  The <a href=\\"/tutorials/content-map\\">concept map</a> explains how the parts fit\\n  together, which chapters provide the primary explanation for each major\\n  concept, and where later chapters revisit the same idea as an implementation,\\n  enterprise, or reference view.\\n</div>\\n\\n<section class=\\"tr-card\\" style=\\"margin: 18px 0 6px;\\">\\n  <h2 style=\\"margin-top:0\\" id=\\"how-to-read-this-book\\">How to read this book</h2>\\n  <p>The book has six parts. They are presented in the order an enterprise\\n  team usually encounters them \u2014 delivery first, then platform, then agents,\\n  then the ML/DL fundamentals that power them. <strong>If you are a new\\n  learner, you almost certainly want to read the parts in a different order.</strong>\\n  Pick the path that matches your role:</p>\\n\\n  <h3 id=\\"new-to-ml-or-just-learning-the-field\\">New to ML or just learning the field</h3>\\n  <ol>\\n    <li><a href=\\"/tutorials/part4-ml-foundations/overview\\">Part IV \u2014 ML Foundations</a> (PyTorch, regression, classification, trees)</li>\\n    <li><a href=\\"/tutorials/part5-deep-learning-and-llms/overview\\">Part V \u2014 Deep Learning &amp; LLMs</a> in order: FFN \u2192 CNN \u2192 RNN \u2192 Transformers \u2192 fine\u2011tuning \u2192 alignment</li>\\n    <li><a href=\\"/tutorials/part3-agent-protocols/overview\\">Part III \u2014 Agent Protocols</a> once you understand what an LLM is</li>\\n    <li><a href=\\"/tutorials/part2-backend-platform-security/overview\\">Part II</a> and <a href=\\"/tutorials/part1-enterprise-ai-delivery/overview\\">Part I</a> when you start shipping</li>\\n  </ol>\\n\\n  <h3 id=\\"backend-platform-engineer-learning-ai\\">Backend / platform engineer learning AI</h3>\\n  <ol>\\n    <li><a href=\\"/tutorials/part2-backend-platform-security/overview\\">Part II</a> chapters 1\u20136 (FastAPI, Pydantic contracts, concurrency, background work) \u2014 already familiar territory</li>\\n    <li><a href=\\"/tutorials/part2-backend-platform-security/overview\\">Part II</a> chapters 7\u201316 for the auth + identity + multi\u2011tenancy stack</li>\\n    <li><a href=\\"/tutorials/part3-agent-protocols/overview\\">Part III</a> end\u2011to\u2011end (MCP \u2192 A2A \u2192 LangChain)</li>\\n    <li>Spot\u2011read <a href=\\"/tutorials/part5-deep-learning-and-llms/11-transformers-and-attention\\">Transformers (Part V Ch. 11)</a>, <a href=\\"/tutorials/part5-deep-learning-and-llms/12-llm-fine-tuning\\">fine\u2011tuning (Ch. 12)</a>, and <a href=\\"/tutorials/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo\\">alignment (Ch. 13)</a></li>\\n    <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/overview\\">Part I</a> when you take your first AI project to production</li>\\n  </ol>\\n\\n  <h3 id=\\"lead-principal-ai-engineer-or-architect\\">Lead / Principal AI engineer or architect</h3>\\n  <ol>\\n    <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/overview\\">Part I</a> end\u2011to\u2011end (delivery lifecycle)</li>\\n    <li><a href=\\"/tutorials/part2-backend-platform-security/06-sso-oauth2-oidc-primer\\">Part II Ch. 7\u201316</a> for the auth/identity story you\'ll review</li>\\n    <li><a href=\\"/tutorials/part3-agent-protocols/overview\\">Part III</a> for protocol\u2011level vocabulary in design reviews</li>\\n    <li><a href=\\"/tutorials/part5-deep-learning-and-llms/11-transformers-and-attention\\">Transformers</a>, <a href=\\"/tutorials/part5-deep-learning-and-llms/12-llm-fine-tuning\\">fine\u2011tuning</a>, <a href=\\"/tutorials/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo\\">alignment</a> as conceptual reference</li>\\n    <li><a href=\\"/tutorials/part6-appendices/01-lead-ds-interview-talk-track\\">Appendix A</a> for a 60\u2011minute narrative covering all of the above</li>\\n  </ol>\\n\\n  <h3 id=\\"preparing-for-a-lead-ds-lead-ai-interview\\">Preparing for a Lead DS / Lead AI interview</h3>\\n  <ol>\\n    <li><a href=\\"/tutorials/part6-appendices/01-lead-ds-interview-talk-track\\">Appendix A \u2014 Lead DS interview talk track</a> (start here)</li>\\n    <li>Drill the <a href=\\"/tutorials/part1-enterprise-ai-delivery/overview\\">delivery lifecycle</a> and <a href=\\"/tutorials/part2-backend-platform-security/09-authentication-deep-dive\\">auth deep\u2011dive</a></li>\\n    <li>Be able to whiteboard <a href=\\"/tutorials/part5-deep-learning-and-llms/11-transformers-and-attention\\">attention</a> and explain the difference between <a href=\\"/tutorials/part5-deep-learning-and-llms/12-llm-fine-tuning\\">SFT/PEFT/DPO</a> and <a href=\\"/tutorials/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo\\">ORPO/GRPO/KTO</a></li>\\n  </ol>\\n\\n  <p style=\\"margin-bottom:0\\"><strong>Reading the book front\u2011to\u2011back</strong> is\\n  also valid \u2014 it tells the story from the business side inward. Just be\\n  aware that Part III assumes Part II Ch. 1\u20133, and Part V assumes Part IV.</p>\\n</section>\\n\\n<div class=\\"tr-toc-grid\\">\\n\\n  <article class=\\"tr-card\\">\\n    <span class=\\"tr-card-tag\\">part-i \xb7 delivery-leadership</span>\\n    <h3 id=\\"part-i-enterprise-ai-delivery-lifecycle\\"><a href=\\"/tutorials/part1-enterprise-ai-delivery/overview\\">Part I \u2014 Enterprise AI Delivery Lifecycle</a></h3>\\n    <p>From a business pain point to a shipped pilot: intake, response,\\n       kickoff, HLD/LLD, architecture review, provisioning, and scale.</p>\\n    <ol>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/01-business-pain-to-ai-lead\\">From business pain to AI lead</a></li>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/02-intake-package\\">The intake package</a></li>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/03-ai-lead-response\\">AI lead response document</a></li>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/04-kickoff-meeting\\">Pilot kickoff meeting</a></li>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/05-seven-days-after-kickoff\\">Seven days after kickoff</a></li>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/06-architecture-reference-design\\">Architecture reference design</a></li>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/07-hld-service-selection\\">HLD and service selection</a></li>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/08-after-hld-next-steps\\">After HLD: next steps</a></li>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/09-architecture-review\\">Architecture review</a></li>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan\\">HLD \u2192 LLD &amp; sprint plan</a></li>\\n      <li><a href=\\"/tutorials/part1-enterprise-ai-delivery/11-provisioning-services-scale\\">Provisioning, services, scale</a></li>\\n    </ol>\\n  </article>\\n\\n  <article class=\\"tr-card\\">\\n    <span class=\\"tr-card-tag\\">part-ii \xb7 platform-engineering</span>\\n    <h3 id=\\"part-ii-backend-platform-and-security\\"><a href=\\"/tutorials/part2-backend-platform-security/overview\\">Part II \u2014 Backend, Platform &amp; Security</a></h3>\\n    <p>FastAPI fundamentals, Pydantic data contracts, concurrency &amp; user\\n       isolation, background work, the full auth stack\\n       (OIDC/OAuth2/PKCE/JWT), workload identity, multi\u2011tenancy, external\\n       integrations, GitHub governance, and <em>modern auth additions</em>\\n       (Passkeys/WebAuthn, DPoP, mTLS).</p>\\n    <ol>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/01-fastapi-uvicorn-basics\\">FastAPI &amp; Uvicorn basics</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/02-http-methods\\">HTTP methods</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/03-fastapi-request-mapping\\">FastAPI request mapping</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/04-pydantic-data-models\\">Pydantic data models</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/04-concurrency-user-isolation\\">Concurrency &amp; user isolation</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/05-background-tasks-and-retries\\">Background tasks &amp; retries</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/06-sso-oauth2-oidc-primer\\">SSO / OAuth2 / OIDC primer</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi\\">OIDC + OAuth2 + PKCE in FastAPI</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/08-registering-new-users\\">Registering new users</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/09-authentication-deep-dive\\">Authentication deep dive</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/15-modern-auth-additions\\">Modern auth additions (Passkeys, DPoP, mTLS)</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/10-enduser-vs-workload-identity\\">End\u2011user vs workload identity</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/12-tenant-iam-ad-groups\\">Tenant isolation, IAM &amp; AD groups</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/11-gcp-workload-identity\\">GCP workload identity</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/13-external-service-integration\\">External service integration</a></li>\\n      <li><a href=\\"/tutorials/part2-backend-platform-security/14-github-governance\\">GitHub governance &amp; CI</a></li>\\n    </ol>\\n  </article>\\n\\n  <article class=\\"tr-card\\">\\n    <span class=\\"tr-card-tag\\">part-iii \xb7 agents-mcp-a2a</span>\\n    <h3 id=\\"part-iii-agent-protocols-and-integration\\"><a href=\\"/tutorials/part3-agent-protocols/overview\\">Part III \u2014 Agent Protocols &amp; Integration</a></h3>\\n    <p>MCP from first principles through the enterprise pattern and its\\n       2025-to-2026 protocol evolution, A2A 1.0 for multi-agent collaboration,\\n       plus a JS/TS primer and the LangChain \u2192 LangGraph \u2192 Flowise journey.</p>\\n    <ol>\\n      <li><a href=\\"/tutorials/part3-agent-protocols/01-mcp-fundamentals\\">MCP fundamentals</a></li>\\n      <li><a href=\\"/tutorials/part3-agent-protocols/02-mcp-discovery-remote-auth\\">MCP discovery, remote &amp; auth</a></li>\\n      <li><a href=\\"/tutorials/part3-agent-protocols/03-mcp-enterprise-pattern\\">MCP enterprise pattern</a></li>\\n      <li><a href=\\"/tutorials/part3-agent-protocols/04-mcp-2025-update\\">MCP protocol evolution: 2025 foundations to the 2026 stateless core</a></li>\\n      <li><a href=\\"/tutorials/part3-agent-protocols/05-a2a-protocol\\">A2A protocol 1.0</a></li>\\n      <li><a href=\\"/tutorials/part3-agent-protocols/06-javascript-typescript-primer\\">JavaScript &amp; TypeScript primer</a></li>\\n      <li><a href=\\"/tutorials/part3-agent-protocols/07-langchain-langgraph-flowise\\">LangChain \u2192 LangGraph \u2192 Flowise</a></li>\\n    </ol>\\n  </article>\\n\\n  <article class=\\"tr-card\\">\\n    <span class=\\"tr-card-tag\\">part-iv \xb7 classical-ml</span>\\n    <h3 id=\\"part-iv-ml-foundations\\"><a href=\\"/tutorials/part4-ml-foundations/overview\\">Part IV \u2014 ML Foundations</a></h3>\\n    <p>The geometric view of ML, linear regression and classification in\\n       PyTorch, and the tree/ensemble family (Random Forest, AdaBoost,\\n       Gradient Boosting, XGBoost).</p>\\n    <ol>\\n      <li><a href=\\"/tutorials/part4-ml-foundations/01-introduction-pytorch\\">PyTorch foundations</a></li>\\n      <li><a href=\\"/tutorials/part4-ml-foundations/02-ml-as-geometry\\">ML as geometry</a></li>\\n      <li><a href=\\"/tutorials/part4-ml-foundations/03-linear-regression\\">Linear regression</a></li>\\n      <li><a href=\\"/tutorials/part4-ml-foundations/04-linear-classification\\">Linear classification</a></li>\\n      <li><a href=\\"/tutorials/part4-ml-foundations/05-trees-bagging-boosting\\">Trees, bagging &amp; boosting</a></li>\\n    </ol>\\n  </article>\\n\\n  <article class=\\"tr-card\\">\\n    <span class=\\"tr-card-tag\\">part-v \xb7 neural-nets-llms</span>\\n    <h3 id=\\"part-v-deep-learning-and-llms\\"><a href=\\"/tutorials/part5-deep-learning-and-llms/overview\\">Part V \u2014 Deep Learning &amp; LLMs</a></h3>\\n    <p>From the single neuron to feed\u2011forward nets, CNNs, sequence models,\\n       and into Transformers, LLM fine\u2011tuning, and modern alignment\\n       methods such as ORPO, GRPO, and KTO.</p>\\n    <ol>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/01-ffn-concepts\\">FFN concepts</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/02-ffn-training-debugging\\">FFN training &amp; debugging</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/03-ffn-canonical-merged\\">FFN single-chapter reference</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/04-cnn-convolution\\">CNN \u2014 convolution</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/05-cnn-architecture\\">CNN \u2014 architecture</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/06-cnn-pytorch-implementation\\">CNN \u2014 PyTorch implementation</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/07-cnn-dropout-train-eval\\">CNN \u2014 dropout &amp; train/eval</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/08-forecasting-sequence-data\\">Forecasting &amp; sequence data</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/09-autoregressive-linear-model\\">Autoregressive linear model</a></li>\\n      <li><a href=\\"/tutorials/labs/rnn\\"><em>Companion lab:</em> animated RNN walkthrough</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/10-recurrent-neural-networks\\">Recurrent neural networks</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/11-transformers-and-attention\\">Transformers &amp; attention</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/12-llm-fine-tuning\\">LLM fine\u2011tuning</a></li>\\n      <li><a href=\\"/tutorials/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo\\">Modern LLM alignment: ORPO, GRPO, KTO</a></li>\\n    </ol>\\n  </article>\\n\\n  <article class=\\"tr-card\\">\\n    <span class=\\"tr-card-tag\\">part-vi \xb7 reference</span>\\n    <h3 id=\\"part-vi-appendices\\"><a href=\\"/tutorials/part6-appendices/overview\\">Part VI \u2014 Appendices</a></h3>\\n    <p>Lead Data Science interview talk track and the LaTeX print edition\\n       of the classification chapter.</p>\\n    <ol>\\n      <li><a href=\\"/tutorials/part6-appendices/01-lead-ds-interview-talk-track\\">Appendix A \u2014 Lead DS interview talk track</a></li>\\n      <li><a href=\\"/tutorials/part6-appendices/02-classification-latex-print\\">Appendix B \u2014 Classification (LaTeX print)</a></li>\\n    </ol>\\n  </article>\\n\\n</div>"}'),s={title:"Enterprise AI, Agents & Applied ML",slug:"/",description:"A practical book for moving from enterprise AI delivery and backend platform foundations into agent protocols, applied machine learning, deep learning, LLM fine\u2011tuning, and alignment. It is organized as a sequence of...",sidebar_label:"Book home",pagination_label:"Book home",hide_title:!0,hide_table_of_contents:!0},p=void 0,d={},c=[];function u(e){return(0,n.jsx)(l.A,{content:o})}function h(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(u,{...e})}):u()}}}]);